class.description:
Ressource de configuration : l'état (charges, recharge, activation) est conservé par l'[AbilitySystem], une même ressource peut donc être partagée entre plusieurs entités. Déroulement d'une activation ([method AbilitySystem.activate]) : vérification des conditions, paiement des [member costs], consommation d'une charge ; après [member cast_time], application des [member effects_on_self] et [member effects_on_target] ; fin après [member active_duration]. Comportement sur mesure par script ([code]extends Ability[/code]) : [method _can_activate], [method _on_activate], [method _on_commit], [method _on_tick], [method _on_end]. [codeblock] # boule_de_feu.gd : lance un projectile à la fin de l'incantation. extends Ability
@export var projectile: PackedScene
func _on_commit(system: Node, target: Node) -> void: var lanceur := system.get_parent() as Node2D var boule := projectile.instantiate() as Node2D lanceur.add_sibling(boule) boule.global_position = lanceur.global_position if target: boule.look_at(target.global_position) [/codeblock]
